import openpyxl
from pathlib import Path

BASE_DIR = Path(__file__).resolve().parent.parent
EXCEL_PATH = BASE_DIR / "sample-data" / "saravanan_actual_stock_master.xlsx"
EXCEL_PATH.parent.mkdir(parents=True, exist_ok=True)

# Define dates: 2026-10-01 to 2026-10-31
DATES = [f"2026-10-{d:02d}" for d in range(1, 32)]

wb = openpyxl.Workbook()
wb.remove(wb.active)  # Remove default sheet

def setup_sheet(title, rows_data):
    ws = wb.create_sheet(title=title)
    
    # Row 1: Date headers spanning 3 columns each
    row1 = ["", "", "", "", "", "OPENING STOCK", "", ""]
    for d in DATES:
        row1.extend([d, "", ""])
    row1.extend(["CLOSING", "", "", ""])
    ws.append(row1)

    # Row 2: Detailed Column Headers
    row2 = ["Sl No", "Description", "Part No", "Category", "UOM", "OPENING STOCK", "UNIT PRICE", "AMOUNT"]
    for _ in DATES:
        row2.extend(["OPENING STOCK", "IN", "OUT"])
    row2.extend(["OPENING STOCK", "TOTAL RECEIPTS", "TOTAL ISSUE", "CLOSING STK"])
    ws.append(row2)

    # Append product rows
    for r in rows_data:
        ws.append(r)

